inline bool VerifyBBValueU(::flatbuffers::Verifier &verifier, const void *obj, BBValueU type) {
  switch (type) {
    case BBValueU::NONE: {
      return true;
    }
    case BBValueU::Float: {
      return verifier.VerifyField<SE::FlatBuffers::Float>(static_cast<const uint8_t *>(obj), 0, 4);
    }
    case BBValueU::Bool: {
      return verifier.VerifyField<SE::FlatBuffers::Bool>(static_cast<const uint8_t *>(obj), 0, 1);
    }
    case BBValueU::Int: {
      return verifier.VerifyField<SE::FlatBuffers::Int>(static_cast<const uint8_t *>(obj), 0, 4);
    }
    case BBValueU::Vec3: {
      return verifier.VerifyField<SE::FlatBuffers::Vec3>(static_cast<const uint8_t *>(obj), 0, 4);
    }
    default: return true;
  }
}

inline bool VerifyBBValueUVector(::flatbuffers::Verifier &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<BBValueU> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyBBValueU(
        verifier,  values->Get(i), types->GetEnum<BBValueU>(i))) {
      return false;
    }
  }
  return true;
}

inline void *BBValueUUnion::UnPack(const void *obj, BBValueU type, const ::flatbuffers::resolver_function_t *resolver) {
  (void)resolver;
  switch (type) {
    case BBValueU::Float: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::Float *>(obj);
      return new SE::FlatBuffers::Float(*ptr);
    }
    case BBValueU::Bool: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::Bool *>(obj);
      return new SE::FlatBuffers::Bool(*ptr);
    }
    case BBValueU::Int: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::Int *>(obj);
      return new SE::FlatBuffers::Int(*ptr);
    }
    case BBValueU::Vec3: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::Vec3 *>(obj);
      return new SE::FlatBuffers::Vec3(*ptr);
    }
    default: return nullptr;
  }
}

inline ::flatbuffers::Offset<void> BBValueUUnion::Pack(::flatbuffers::FlatBufferBuilder &_fbb, const ::flatbuffers::rehasher_function_t *_rehasher) const {
  (void)_rehasher;
  switch (type) {
    case BBValueU::Float: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::Float *>(value);
      return _fbb.CreateStruct(*ptr).Union();
    }
    case BBValueU::Bool: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::Bool *>(value);
      return _fbb.CreateStruct(*ptr).Union();
    }
    case BBValueU::Int: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::Int *>(value);
      return _fbb.CreateStruct(*ptr).Union();
    }
    case BBValueU::Vec3: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::Vec3 *>(value);
      return _fbb.CreateStruct(*ptr).Union();
    }
    default: return 0;
  }
}

inline BBValueUUnion::BBValueUUnion(const BBValueUUnion &u) : type(u.type), value(nullptr) {
  switch (type) {
    case BBValueU::Float: {
      value = new SE::FlatBuffers::Float(*reinterpret_cast<SE::FlatBuffers::Float *>(u.value));
      break;
    }
    case BBValueU::Bool: {
      value = new SE::FlatBuffers::Bool(*reinterpret_cast<SE::FlatBuffers::Bool *>(u.value));
      break;
    }
    case BBValueU::Int: {
      value = new SE::FlatBuffers::Int(*reinterpret_cast<SE::FlatBuffers::Int *>(u.value));
      break;
    }
    case BBValueU::Vec3: {
      value = new SE::FlatBuffers::Vec3(*reinterpret_cast<SE::FlatBuffers::Vec3 *>(u.value));
      break;
    }
    default:
      break;
  }
}

inline void BBValueUUnion::Reset() {
  switch (type) {
    case BBValueU::Float: {
      auto ptr = reinterpret_cast<SE::FlatBuffers::Float *>(value);
      delete ptr;
      break;
    }
    case BBValueU::Bool: {
      auto ptr = reinterpret_cast<SE::FlatBuffers::Bool *>(value);
      delete ptr;
      break;
    }
    case BBValueU::Int: {
      auto ptr = reinterpret_cast<SE::FlatBuffers::Int *>(value);
      delete ptr;
      break;
    }
    case BBValueU::Vec3: {
      auto ptr = reinterpret_cast<SE::FlatBuffers::Vec3 *>(value);
      delete ptr;
      break;
    }
    default: break;
  }
  value = nullptr;
  type = BBValueU::NONE;
}

